python -c "
import os
for root, dirs, files in os.walk('.'):
    for f in files:
        if f == 'models.py':
            path = os.path.join(root, f)
            with open(path) as fp:
                content = fp.read()
            if 'class Meta:' not in content:
                with open(path, 'a') as fp:
                    fp.write('\n    class Meta:\n        app_label = \'{}\'\n'.format(os.path.basename(root)))
